 static IEnumerator Run(){var app=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();var root=new GameObject("Temporary character review");var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None);foreach(var c in canvases)c.enabled=false;app.world.gameObject.SetActive(false);app.gameCamera.enabled=false;var cgo=new GameObject("Gallery camera",typeof(Camera));var camera=cgo.GetComponent<Camera>();camera.transform.position=new Vector3(0,3.4f,-15);camera.orthographic=true;camera.orthographicSize=4.15f;camera.backgroundColor=RestaurantPreview.Models.C("#EEE5D1");camera.clearFlags=CameraClearFlags.SolidColor;var lightGo=new GameObject("Gallery fill",typeof(Light));lightGo.GetComponent<Light>().type=LightType.Directional;lightGo.GetComponent<Light>().intensity=1;lightGo.transform.rotation=Quaternion.Euler(40,-35,0);for(int i=0;i<12;i++){float x=(i%3-1)*1.6f,y=5.6f-(i/3)*1.8f;var guest=UnityEngine.Object.Instantiate(app.catalog.guestVariants[i],new Vector3(x,y,0),Quaternion.identity,root.transform);var label=new GameObject("Look label",typeof(TextMeshPro));label.transform.SetParent(root.transform);label.transform.position=new Vector3(x,y-.15f,-.2f);var t=label.GetComponent<TextMeshPro>();t.text=new[]{"Bob + glasses","Side part","Ponytail","Curls","Bun + glasses","Short fade","Braids","Beanie","Waves + glasses","Tied back","Pixie","Beard + glasses"}[i];t.fontSize=1.8f;t.alignment=TextAlignmentOptions.Center;t.color=RestaurantPreview.Models.C("#304D40");t.rectTransform.sizeDelta=new Vector2(1.55f,.3f);}
 yield return new WaitForEndOfFrame();var tex=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,tex.width,tex.height),0,0);tex.Apply();File.WriteAllBytes("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/CharacterGallery.png",tex.EncodeToPNG());UnityEngine.Object.Destroy(tex);UnityEngine.Object.Destroy(root);UnityEngine.Object.Destroy(cgo);UnityEngine.Object.Destroy(lightGo);foreach(var c in canvases)if(c)c.enabled=true;app.gameCamera.enabled=true;app.world.gameObject.SetActive(true);}
